document.addEventListener("DOMContentLoaded",()=>{const t=document.body,e=document.getElementById("theme-toggle");if(!e)return;window.addEventListener("keydown",t=>{const n=document.activeElement?.tagName.toLowerCase();if(t.ctrlKey||t.metaKey||t.altKey||t.shiftKey)return;if(t.key.toLowerCase()!=="t")return;if(n==="input"&&document.activeElement?.type!=="checkbox"||n==="textarea"||document.activeElement?.isContentEditable)return;t.preventDefault(),e.checked=!e.checked,e.dispatchEvent(new Event("change"))},!0),e.addEventListener("change",function(){this.checked?(document.documentElement.classList.add("dark-mode"),localStorage.setItem("darkMode","true")):(document.documentElement.classList.remove("dark-mode"),localStorage.removeItem("darkMode"))}),localStorage.getItem("darkMode")&&(e.checked=!0,document.documentElement.classList.add("dark-mode"))})